-- Whether a posting requires the applicant to be a current student. Read by Jev (2 Oct 2026), kept only when confident and internship-type:
--   required = must be enrolled / studying now (internship agreement with a school, thesis, "student is a must")
--   recent   = current students and recent graduates both accepted
--   open     = being a student is not needed, or nothing says so
-- Jev's other calls (full-time graduate programmes, low confidence) are left as open. See scripts/audit/enrollment.py.
alter table public.postings add column if not exists enrollment text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'postings_enrollment_check') then
    alter table public.postings add constraint postings_enrollment_check check (enrollment in ('required','recent','open'));
  end if;
end $$;
comment on column public.postings.enrollment is 'required | recent | open: must the applicant be a current student. Jev reading, internship-type postings, confidence >= 0.85.';
